import{_ as o,a0 as i,w as p,s as b,ao as l,I as a,x as t,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const W=JSON.parse('{"title":"KeeWeb：一个开源且跨平台的密码管理工具 | LCTT x X-CMD","titleTemplate":false,"description":"KeeWeb：一个开源且跨平台的密码管理工具 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KeeWeb：一个开源且跨平台的密码管理工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KeeWeb：一个开源且跨平台的密码管理工具 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181008 KeeWeb - An Open Source, Cross Platform Password Manager","title":"KeeWeb：一个开源且跨平台的密码管理工具","tag":"201811","desc":""},"relativePath":"201811/20181008 KeeWeb - An Open Source, Cross Platform Password Manager.md","filePath":"[post].md"}'),d={name:"201811/20181008 KeeWeb - An Open Source, Cross Platform Password Manager.md"};function u(w,e,h,m,g,f){const s=i("Link");return p(),b("div",null,[e[29]||(e[29]=l('<h1 id="keeweb-一个开源且跨平台的密码管理工具" tabindex="-1">KeeWeb：一个开源且跨平台的密码管理工具 <a class="header-anchor" href="#keeweb-一个开源且跨平台的密码管理工具" aria-label="Permalink to “KeeWeb：一个开源且跨平台的密码管理工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/keeweb-720x340.png" alt=""></p><p>如果你长时间使用互联网，那很可能在很多网站上都有很多帐户。所有这些帐户都必须有密码，而且必须记住所有的密码，或者把它们写下来。在纸上写下密码可能不安全，如果有多个密码，记住它们实际上是不可能的。这就是密码管理工具在过去几年中大受欢迎的原因。密码管理工具就像一个中央存储库，你可以在其中存储所有帐户的所有密码，并为它设置一个主密码。使用这种方法，你唯一需要记住的只有主密码。</p><p><strong>KeePass</strong> 就是一个这样的开源密码管理工具，它有一个官方客户端，但功能非常简单。也有许多 PC 端和手机端的其他密码管理工具，并且与 KeePass 存储加密密码的文件格式兼容。其中一个就是 <strong>KeeWeb</strong>。</p><p>KeeWeb 是一个开源、跨平台的密码管理工具，具有云同步，键盘快捷键和插件等功能。KeeWeb使用 Electron 框架，这意味着它可以在 Windows、Linux 和 Mac OS 上运行。</p><h3 id="keeweb-的使用" tabindex="-1">KeeWeb 的使用 <a class="header-anchor" href="#keeweb-的使用" aria-label="Permalink to “KeeWeb 的使用”">​</a></h3><p>有两种方式可以使用 KeeWeb。第一种无需安装，直接在网页上使用，第二中就是在本地系统中安装 KeeWeb 客户端。</p><h4 id="在网页上使用-keeweb" tabindex="-1">在网页上使用 KeeWeb <a class="header-anchor" href="#在网页上使用-keeweb" aria-label="Permalink to “在网页上使用 KeeWeb”">​</a></h4>',8)),a("p",null,[e[1]||(e[1]=t("如果不想在系统中安装应用，可以去 ",-1)),n(s,{href:"https://app.keeweb.info/"},{default:r(()=>[...e[0]||(e[0]=[t("https://app.keeweb.info/",-1)])]),_:1}),e[2]||(e[2]=t(" 使用KeeWeb。",-1))]),e[30]||(e[30]=a("p",null,[a("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-webapp.png",alt:""})],-1)),e[31]||(e[31]=a("p",null,"网页端具有桌面客户端的所有功能，当然也需要联网才能进行使用。",-1)),e[32]||(e[32]=a("h4",{id:"在计算机中安装-keeweb",tabindex:"-1"},[t("在计算机中安装 KeeWeb "),a("a",{class:"header-anchor",href:"#在计算机中安装-keeweb","aria-label":"Permalink to “在计算机中安装 KeeWeb”"},"​")],-1)),e[33]||(e[33]=a("p",null,"如果喜欢客户端的舒适性和离线可用性，也可以将其安装在系统中。",-1)),a("p",null,[e[4]||(e[4]=t("如果使用 Ubuntu/Debian，你可以去 ",-1)),n(s,{href:"https://github.com/keeweb/keeweb/releases/latest"},{default:r(()=>[...e[3]||(e[3]=[t("发布页",-1)])]),_:1}),e[5]||(e[5]=t(" 下载 KeeWeb 最新的 .deb 文件，然后通过下面的命令进行安装：",-1))]),e[34]||(e[34]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg -i KeeWeb-1.6.3.linux.x64.deb</span></span></code></pre></div>',1)),a("p",null,[e[8]||(e[8]=t("如果用的是 Arch，在 ",-1)),n(s,{href:"https://aur.archlinux.org/packages/keeweb/"},{default:r(()=>[...e[6]||(e[6]=[t("AUR",-1)])]),_:1}),e[9]||(e[9]=t(" 上也有 KeeWeb，可以使用任何 AUR 助手进行安装，例如 ",-1)),n(s,{href:"https://www.ostechnix.com/yay-found-yet-another-reliable-aur-helper/"},{default:r(()=>[...e[7]||(e[7]=[t("Yay",-1)])]),_:1}),e[10]||(e[10]=t("：",-1))]),e[35]||(e[35]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S keeweb</span></span></code></pre></div><p>安装后，从菜单中或应用程序启动器启动 KeeWeb。默认界面如下：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-desktop-client.png" alt=""></p><h3 id="总体布局" tabindex="-1">总体布局 <a class="header-anchor" href="#总体布局" aria-label="Permalink to “总体布局”">​</a></h3><p>KeeWeb 界面主要显示所有密码的列表，在左侧展示所有标签。单击标签将对密码进行筛选，只显示带有那个标签的密码。在右侧，显示所选帐户的所有字段。你可以设置用户名、密码、网址，或者添加自定义的备注。你甚至可以创建自己的字段并将其标记为安全字段，这在存储信用卡信息等内容时非常有用。你只需单击即可复制密码。 KeeWeb 还显示账户的创建和修改日期。已删除的密码会保留在回收站中，可以在其中还原或永久删除。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-general-layout.png" alt=""></p><h3 id="keeweb-功能" tabindex="-1">KeeWeb 功能 <a class="header-anchor" href="#keeweb-功能" aria-label="Permalink to “KeeWeb 功能”">​</a></h3><h4 id="云同步" tabindex="-1">云同步 <a class="header-anchor" href="#云同步" aria-label="Permalink to “云同步”">​</a></h4><p>KeeWeb 的主要功能之一是支持各种远程位置和云服务。除了加载本地文件，你可以从以下位置打开文件：</p><ol><li>WebDAV Servers</li><li>Google Drive</li><li>Dropbox</li><li>OneDrive</li></ol><p>这意味着如果你使用多台计算机，就可以在它们之间同步密码文件，因此不必担心某台设备无法访问所有密码。</p><h4 id="密码生成器" tabindex="-1">密码生成器 <a class="header-anchor" href="#密码生成器" aria-label="Permalink to “密码生成器”">​</a></h4><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-password-generator.png" alt=""></p><p>除了对密码进行加密之外，为每个帐户创建新的强密码也很重要。这意味着，如果你的某个帐户遭到入侵，攻击者将无法使用相同的密码进入其他帐户。</p><p>为此，KeeWeb 有一个内置密码生成器，可以生成特定长度、包含指定字符的自定义密码。</p><h4 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to “插件”">​</a></h4><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-plugins.png" alt=""></p>',17)),a("p",null,[e[12]||(e[12]=t("你可以使用插件扩展 KeeWeb 的功能。其中一些插件用于更改界面语言，而其他插件则添加新功能，例如访问 ",-1)),n(s,{href:"https://haveibeenpwned.com"},{default:r(()=>[...e[11]||(e[11]=[t("https://haveibeenpwned.com",-1)])]),_:1}),e[13]||(e[13]=t(" 以查看密码是否暴露。",-1))]),e[36]||(e[36]=l('<h4 id="本地备份" tabindex="-1">本地备份 <a class="header-anchor" href="#本地备份" aria-label="Permalink to “本地备份”">​</a></h4><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/KeeWeb-backup.png" alt=""></p><p>无论密码文件存储在何处，你都应该在计算机上保留一份本地备份。幸运的是，KeeWeb 内置了这个功能。你可以备份到特定路径，并将其设置为定期备份，或者只在文件更改时进行备份。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>我实际使用 KeeWeb 已经好几年了，它完全改变了我存储密码的方式。云同步是我长期使用 KeeWeb 的主要功能，这样我不必担心在多个设备上保存多个不同步的文件。如果你想要一个具有云同步功能的密码管理工具，KeeWeb 就是你应该关注的东西。</p><hr>',6)),a("p",null,[e[15]||(e[15]=t("via: ",-1)),n(s,{href:"https://www.ostechnix.com/keeweb-an-open-source-cross-platform-password-manager/"},{default:r(()=>[...e[14]||(e[14]=[t("https://www.ostechnix.com/keeweb-an-open-source-cross-platform-password-manager/",-1)])]),_:1})]),a("p",null,[e[20]||(e[20]=t("作者：",-1)),n(s,{href:"https://www.ostechnix.com/author/editor/"},{default:r(()=>[...e[16]||(e[16]=[t("EDITOR",-1)])]),_:1}),e[21]||(e[21]=t(" 选题：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[17]||(e[17]=[t("lujun9972",-1)])]),_:1}),e[22]||(e[22]=t(" 译者：",-1)),n(s,{href:"https://github.com/jlztan"},{default:r(()=>[...e[18]||(e[18]=[t("jlztan",-1)])]),_:1}),e[23]||(e[23]=t(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:r(()=>[...e[19]||(e[19]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[26]||(e[26]=t("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[24]||(e[24]=[t("LCTT",-1)])]),_:1}),e[27]||(e[27]=t(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:r(()=>[...e[25]||(e[25]=[t("Linux中国",-1)])]),_:1}),e[28]||(e[28]=t(" 荣誉推出",-1))])])}const x=o(d,[["render",u]]);export{W as __pageData,x as default};
